var i=`1130-biscuits-and-gravy`;var n=`world-1130`;var r=`US`;var a=`northern-america`;var o=8;var s=53;var u={en:`Biscuits and Gravy`,ua:`Бісквіти з підливою`};var d={en:`Biscuits and Gravy is a dish from United States prepared with all-purpose flour, baking powder, buttermilk, ground pork. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Бісквіти з підливою, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: пшеничне борошно універсальне, розпушувач тіста, сколотини, свинячий фарш. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,410,`g`],[`baking-powder`,19,`g`],[`table-salt`,6,`g`],[`unsalted-butter`,110,`g`],[`buttermilk`,310,`ml`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 18 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 18 хвилин до готовності.`,t:[`baking`],m:18,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`ground-pork`,430,`g`],[`unsalted-butter`,25,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 10 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 10 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:10,i:[[`all-purpose-flour`,40,`g`],[`whole-cow-milk`,650,`ml`],[`ground-black-pepper`,6,`g`]]}];var g={slug:i,id:n,country:`US`,region:a,servings:8,minutes:53,title:u,text:d,steps:l};export{r as country,g as default,n as id,s as minutes,a as region,o as servings,i as slug,l as steps,d as text,u as title};